import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import FloatingList from "./FloatingList.tsx";
import { ChevronDownSvg, ChevronUpSvg } from "./chevrons.tsx";
import { useOutsideClick } from "../../hooks/useOutsideClick.ts";
import { classNames } from "../../utils/classNames.ts";
import { indT } from "../../utils/indI18n.ts";
import type { FloatingWidthStrategy } from "../../hooks/useFloatingPosition.ts";

type RawOption =
  | {
      value?: string | number;
      Value?: string | number;
      text?: string;
      Text?: string;
      icon?: React.ReactNode;
      Icon?: React.ReactNode;
    }
  | [string | number, string];

type NormalizedOption = {
  value: string | number;
  text: string;
  icon?: React.ReactNode;
};

const EMPTY_OPTION: NormalizedOption = { value: "", text: "" };
const DESKTOP_DROPDOWN_MAX_WIDTH_PX = 480;

const normalizeOption = (o: RawOption): NormalizedOption => {
  if (Array.isArray(o)) {
    return { value: o[0] ?? "", text: o[1] ?? "" };
  }

  return {
    value: o?.value ?? o?.Value ?? "",
    text: o?.text ?? o?.Text ?? "",
    icon: o?.icon ?? o?.Icon,
  };
};

const normalizeLookupText = (value: string | number | null | undefined): string => {
  return String(value ?? "").trim().toLowerCase();
};

type SelectComboboxProps = {
  label: string;
  options: RawOption[];
  selectedOption?: RawOption;
  value: string | number;
  onChange: (value: string) => void;
  inputRef?: React.Ref<HTMLInputElement>;
  placeholder?: string;
  invalid?: boolean;
  disabled?: boolean;
  readOnly?: boolean;
  usePortal?: boolean;
  idBase?: string;
  portalClassName?: string;
  panelClassName?: string;
  containerClassName?: string;
  labelClassName?: string;
  showSearchButton?: boolean;
  allowTextInput?: boolean;
  showLabel?: boolean;
  selectedTextMode?: "text" | "value";
  dropdownExpandPx?: number;
  dropdownMinWidthPx?: number;
  dropdownWidthStrategy?: FloatingWidthStrategy;
  /** @deprecated Use dropdownWidthStrategy for explicit responsive behavior. */
  dropdownUseAvailableWidth?: boolean;
  dropdownMaxHeightClass?: string;
  dropdownPlacement?: "bottom" | "top";
  selectedIconClassName?: string;
  optionIconClassName?: string;
  allowOptionHorizontalScroll?: boolean;
  lockDropdownWidthOnFirstOpen?: boolean;
  disableDefaultOptionPadding?: boolean;
  optionLeftPaddingClassName?: string;
  optionTextClassName?: string;
  optionDefaultClassName?: string;
  optionActiveClassName?: string;
  optionSelectedClassName?: string;
  selectedInputPaddingClassName?: string;
  panelStyle?: React.CSSProperties;
  clearOnEmptyInput?: boolean;
  /** Selects the complete editable value whenever the input receives focus or is clicked. */
  selectTextOnFocus?: boolean;
};

// Reusable select combobox with optional portal rendering for the list.
const SelectCombobox = ({
  label,
  options,
  selectedOption,
  value,
  onChange,
  inputRef,
  placeholder,
  invalid = false,
  disabled = false,
  readOnly = false,
  usePortal = true,
  idBase,
  portalClassName,
  panelClassName,
  containerClassName = "space-y-2",
  labelClassName = "form-label font-semibold",
  showSearchButton = false,
  allowTextInput = true,
  showLabel = true,
  selectedTextMode = "text",
  dropdownExpandPx = 0,
  dropdownMinWidthPx = 0,
  dropdownWidthStrategy,
  dropdownUseAvailableWidth,
  dropdownMaxHeightClass = "max-h-72",
  dropdownPlacement = "bottom",
  selectedIconClassName = "h-4 w-4",
  optionIconClassName = "h-4 w-4",
  allowOptionHorizontalScroll = false,
  lockDropdownWidthOnFirstOpen = false,
  disableDefaultOptionPadding = false,
  optionLeftPaddingClassName = "",
  optionTextClassName = "",
  optionDefaultClassName = "text-slate-900",
  optionActiveClassName = "bg-primary text-white",
  optionSelectedClassName = "text-primary",
  selectedInputPaddingClassName = "pl-9",
  panelStyle,
  clearOnEmptyInput = false,
  selectTextOnFocus = false,
}: SelectComboboxProps) => {
  const assignInputRef = (node: HTMLInputElement | null) => {
    if (!inputRef) return;

    if (typeof inputRef === "function") {
      inputRef(node);
      return;
    }

    inputRef.current = node;
  };

  const readOnlyMode = readOnly || disabled;
  const inlineDropdownPlacementClass = dropdownPlacement === "top" ? "bottom-full mb-1" : "mt-1";
  const valueColor = readOnlyMode ? "#64748b" : "#00296be0";
  const data = useMemo(() => {
    return (options || []).map<NormalizedOption>(normalizeOption);
  }, [options]);
  const selectedDataOption = useMemo(() => {
    if (!selectedOption) return null;
    return normalizeOption(selectedOption);
  }, [selectedOption]);
  const selected = useMemo<NormalizedOption>(() => {
    const optionValue = value;
    const normalizedValue = String(optionValue ?? "");
    if (!normalizedValue.trim()) return EMPTY_OPTION;

    return (
      data.find((d) => String(d.value) === normalizedValue) ||
      (selectedDataOption && String(selectedDataOption.value) === normalizedValue ? selectedDataOption : EMPTY_OPTION)
    );
  }, [value, data, selectedDataOption]);
  const selectedValue = String(selected?.value ?? "").trim();

  const [query, setQuery] = useState<string | null>(null);
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);
  const [showNotFoundState, setShowNotFoundState] = useState(false);
  const [previousReadOnlyMode, setPreviousReadOnlyMode] = useState(readOnlyMode);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const boxRef = useRef<HTMLDivElement | null>(null);
  const listRef = useRef<HTMLDivElement | null>(null);
  const initialDropdownWidthRef = useRef<number | null>(null);

  if (previousReadOnlyMode !== readOnlyMode) {
    setPreviousReadOnlyMode(readOnlyMode);
    if (readOnlyMode) {
      if (query !== null) setQuery(null);
      if (showNotFoundState) setShowNotFoundState(false);
      if (open) setOpen(false);
    }
  }

  const clearManualValue = useCallback(
    (nextOpen: boolean, showNotFound: boolean) => {
      setQuery("");
      setActiveIndex(0);
      setShowNotFoundState(showNotFound);
      setOpen(nextOpen);
      onChange("");
    },
    [onChange]
  );
  const outsideClickRefs = useMemo(() => [containerRef, listRef], []);
  const handleOutsideClick = useCallback(() => {
    if (readOnlyMode) {
      setQuery(null);
      setShowNotFoundState(false);
      setOpen(false);
      return;
    }

    if (query !== null) {
      clearManualValue(false, false);
      return;
    }

    setShowNotFoundState(false);
    setOpen(false);
  }, [clearManualValue, query, readOnlyMode]);
  useOutsideClick(outsideClickRefs, handleOutsideClick);

  useEffect(() => {
    if (String(value ?? "").trim()) {
      setQuery(null);
      setShowNotFoundState(false);
    }
  }, [value]);

  const filtered = useMemo(() => {
    if (!query || !query.trim()) return data;
    const normalizedQuery = normalizeLookupText(query);
    return data.filter((option) => {
      const optionValue = normalizeLookupText(option.value);
      const optionText = normalizeLookupText(option.text);
      return optionText.includes(normalizedQuery) || optionValue.includes(normalizedQuery);
    });
  }, [data, query]);
  const selectedIndex = filtered.findIndex((option) => String(option.value) === selectedValue);
  const preferredActiveIndex = selectedIndex >= 0 ? selectedIndex : 0;
  const resolvedActiveIndex =
    filtered.length > 0 ? Math.min(Math.max(activeIndex, 0), filtered.length - 1) : 0;

  const openListAtCurrentSelection = () => {
    if (readOnlyMode) return;
    setActiveIndex(preferredActiveIndex);
    setShowNotFoundState(false);
    setOpen(true);
  };

  const selectOption = (opt: NormalizedOption) => {
    if (readOnlyMode) return;
    const nextValue = String(opt?.value ?? "");
    setQuery(null);
    setShowNotFoundState(false);
    setOpen(false);
    onChange(nextValue);
  };

  const handleKeyDown = (ev: React.KeyboardEvent<HTMLInputElement>) => {
    if (readOnlyMode) return;
    if (ev.key === "ArrowDown") {
      ev.preventDefault();
      if (!open) {
        openListAtCurrentSelection();
        return;
      }
      if (filtered.length) setActiveIndex((idx) => (idx + 1) % filtered.length);
      return;
    }
    if (ev.key === "ArrowUp") {
      ev.preventDefault();
      if (!open) {
        openListAtCurrentSelection();
        return;
      }
      if (filtered.length) setActiveIndex((idx) => (idx - 1 + filtered.length) % filtered.length);
      return;
    }
    if (ev.key === "Enter") {
      ev.preventDefault();
      if (clearOnEmptyInput && query !== null && !query.trim()) {
        setShowNotFoundState(false);
        setOpen(false);
        return;
      }
      if (open && filtered.length) {
        selectOption(filtered[resolvedActiveIndex] ?? filtered[0]);
      } else if (query !== null && query.trim()) {
        clearManualValue(true, true);
      } else {
        openListAtCurrentSelection();
      }
    }
    if (ev.key === "Escape") {
      if (query !== null) {
        clearManualValue(false, false);
        return;
      }

      setShowNotFoundState(false);
      setOpen(false);
    }
  };

  const safeId = String(idBase || label || "select");
  const listId = `select-options-${safeId}`;
  const activeId =
    open && filtered[resolvedActiveIndex] ? `select-opt-${safeId}-${filtered[resolvedActiveIndex].value}` : undefined;
  const listOpen = open && !readOnlyMode;
  const selectedDisplayText = selectedTextMode === "value" ? selectedValue : selected?.text || "";
  const displayValue = query !== null ? query : (selectedValue ? selectedDisplayText : "");
  const showSelectedIcon = query === null && !!selectedValue && !!selected?.icon;
  const showNotFoundRow = showNotFoundState || (!!query && !!query.trim() && filtered.length === 0);
  const normalizedDropdownExpandPx = Number.isFinite(dropdownExpandPx) ? Math.max(0, dropdownExpandPx) : 0;
  const normalizedDropdownMinWidthPx = Number.isFinite(dropdownMinWidthPx) ? Math.max(0, dropdownMinWidthPx) : 0;
  const resolvedDropdownWidthStrategy =
    dropdownWidthStrategy ?? (dropdownUseAvailableWidth === false ? "anchor" : "responsive");

  useEffect(() => {
    if (!lockDropdownWidthOnFirstOpen) return;
    if (!listOpen) return;
    if (initialDropdownWidthRef.current !== null) return;

    const width = boxRef.current?.getBoundingClientRect().width;
    if (!Number.isFinite(width) || !width || width <= 0) return;
    initialDropdownWidthRef.current = width;
  }, [listOpen, lockDropdownWidthOnFirstOpen]);

  const measuredAnchorWidth = boxRef.current?.getBoundingClientRect().width;
  const normalizedMeasuredAnchorWidth =
    Number.isFinite(measuredAnchorWidth) && measuredAnchorWidth && measuredAnchorWidth > 0 ? measuredAnchorWidth : null;
  const fixedDropdownBaseWidth = lockDropdownWidthOnFirstOpen
    ? initialDropdownWidthRef.current ?? normalizedMeasuredAnchorWidth
    : normalizedMeasuredAnchorWidth;
  const fixedDropdownExpandedWidth =
    fixedDropdownBaseWidth !== null && Number.isFinite(fixedDropdownBaseWidth)
      ? fixedDropdownBaseWidth + normalizedDropdownExpandPx
      : null;
  const resolvedDropdownWidthPx =
    fixedDropdownExpandedWidth !== null
      ? Math.max(fixedDropdownExpandedWidth, normalizedDropdownMinWidthPx || 0)
      : null;
  const inlineDropdownStyle: React.CSSProperties | undefined =
    resolvedDropdownWidthPx !== null && resolvedDropdownWidthPx > 0
      ? {
          width: `${resolvedDropdownWidthPx}px`,
          ...(normalizedDropdownMinWidthPx > 0 ? { minWidth: `${normalizedDropdownMinWidthPx}px` } : {}),
        }
      : normalizedDropdownExpandPx > 0
        ? {
            width: `calc(100% + ${normalizedDropdownExpandPx}px)`,
            ...(normalizedDropdownMinWidthPx > 0 ? { minWidth: `${normalizedDropdownMinWidthPx}px` } : {}),
          }
        : normalizedDropdownMinWidthPx > 0
          ? { minWidth: `${normalizedDropdownMinWidthPx}px` }
        : undefined;

  const listBody = (
    <div id={listId} ref={listRef} role="listbox" aria-label={label}>
      {showNotFoundRow ? <div className="px-4 py-2 text-sm text-slate-500">{indT("Common_NotFound", "Not found")}</div> : null}
      {filtered.map((opt, idx) => {
        const sel = selected?.value === opt.value;
        const isActive = idx === resolvedActiveIndex;
        const optionStateClassName = isActive ? optionActiveClassName : sel ? optionSelectedClassName : optionDefaultClassName;
        return (
          <button
            type="button"
            key={String(opt.value)}
            id={`select-opt-${safeId}-${opt.value}`}
            role="option"
            aria-selected={sel}
            className={classNames(
              "relative flex w-full cursor-default select-none items-center py-2 pr-3 text-left text-sm",
              optionLeftPaddingClassName,
              disableDefaultOptionPadding ? "" : "type-option",
              optionStateClassName
            )}
            style={
              allowOptionHorizontalScroll
                ? { overflowX: "auto", overflowY: "hidden", WebkitOverflowScrolling: "touch" }
                : undefined
            }
            onMouseEnter={() => setActiveIndex(idx)}
            onClick={() => selectOption(opt)}
          >
            {sel && (
              <span
                className={classNames(
                  "absolute inset-y-0 left-0 flex items-center pl-2",
                  isActive ? "text-white" : "text-primary"
                )}
              ></span>
            )}
            <span
              className={classNames(
                allowOptionHorizontalScroll ? "inline-flex items-center gap-2" : "flex min-w-0 items-center gap-2",
                sel ? "font-medium" : "font-normal"
              )}
              style={allowOptionHorizontalScroll ? { minWidth: "max-content" } : undefined}
            >
              {opt.icon ? (
                <span
                  className={classNames(
                    "inline-flex shrink-0 items-center justify-center",
                    optionIconClassName,
                    isActive ? "text-white" : "text-slate-500"
                  )}
                >
                  {opt.icon}
                </span>
              ) : null}
              <span
                className={classNames(allowOptionHorizontalScroll ? "block" : "block truncate", optionTextClassName)}
                style={allowOptionHorizontalScroll ? { whiteSpace: "nowrap" } : undefined}
              >
                {opt.text}
              </span>
            </span>
          </button>
        );
      })}
    </div>
  );

  return (
    <div
      className={classNames(containerClassName, disabled ? "pointer-events-none select-none" : "")}
      ref={containerRef}
    >
      {showLabel ? <label className={classNames(labelClassName, invalid ? "text-rose-700" : "")}>{label}</label> : null}
      <div className="relative">
        <div
          ref={boxRef}
          className={classNames(
            "relative w-full cursor-default rounded-[var(--radius-xl)] bg-white text-left focus-within:border-primary focus-within:ring-2 focus-within:ring-primary focus-within:ring-offset-white sm:text-sm",
            readOnlyMode ? "ind-readonly-field" : ""
          )}
          style={readOnlyMode ? { color: valueColor } : undefined}
        >
          <input
            ref={assignInputRef}
            className={classNames(
              "w-full rounded-[var(--radius-xl)] border py-2 text-sm sm:text-base leading-5 focus:outline-hidden focus:ring-2 disabled:bg-slate-100 disabled:text-slate-500 disabled:border-slate-200 disabled:cursor-not-allowed",
              showSelectedIcon ? selectedInputPaddingClassName : "pl-3",
              showSearchButton ? "pr-20" : "pr-10",
              invalid
                ? "border-rose-400 bg-rose-50 focus:ring-rose-200 focus:border-rose-400"
                : "border-slate-200 focus:ring-primary focus:border-primary",
              readOnlyMode ? "ind-readonly-field" : "text-slate-900"
            )}
            style={readOnlyMode ? { color: valueColor } : undefined}
            value={displayValue}
            disabled={disabled}
            onChange={(event) => {
              if (readOnlyMode || !allowTextInput) return;
              const val = event.target.value;
              setActiveIndex(0);
              setShowNotFoundState(false);
              setQuery(val);
              if (clearOnEmptyInput && !val.trim()) {
                clearManualValue(false, false);
                return;
              }
              setOpen(true);
            }}
            onKeyDown={handleKeyDown}
            onFocus={(event) => {
              if (!readOnlyMode) openListAtCurrentSelection();
              if (selectTextOnFocus && !readOnlyMode && allowTextInput) {
                event.currentTarget.select();
              }
            }}
            onClick={(event) => {
              if (selectTextOnFocus && !readOnlyMode && allowTextInput) {
                event.currentTarget.select();
              }
            }}
            placeholder={placeholder}
            readOnly={readOnlyMode || !allowTextInput}
            aria-label={label}
            role="combobox"
            aria-expanded={listOpen}
            aria-controls={listId}
            aria-activedescendant={activeId}
          />
          {showSelectedIcon ? (
            <span className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3 text-slate-500">
              <span className={classNames("inline-flex items-center justify-center", selectedIconClassName)}>{selected.icon}</span>
            </span>
          ) : null}
          <div className="absolute inset-y-0 right-0 flex items-center gap-1 pr-2">
            {showSearchButton ? (
              <button
                type="button"
                className="flex items-center p-1.5 text-slate-400 hover:text-slate-500"
                onClick={() => {
                  if (readOnlyMode) return;
                  if (query !== null && query.trim() && filtered.length === 0) {
                    clearManualValue(true, true);
                    return;
                  }
                  openListAtCurrentSelection();
                }}
                aria-label={indT("Common_Search", "Search")}
                disabled={readOnlyMode}
              >
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="h-5 w-5">
                  <path strokeLinecap="round" strokeLinejoin="round" d="m15.75 15.75-2.489-2.489m0 0a3.375 3.375 0 1 0-4.773-4.773 3.375 3.375 0 0 0 4.774 4.774ZM21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
                </svg>
              </button>
            ) : null}
            <button
              type="button"
              className="flex items-center p-1.5 text-slate-500 hover:text-slate-600"
              onClick={() => {
                if (readOnlyMode) return;
                if (open && query !== null && query.trim()) {
                  clearManualValue(false, false);
                  return;
                }
                if (open) {
                  setOpen(false);
                  return;
                }
                openListAtCurrentSelection();
              }}
              aria-label={open ? indT("Dropdown_HideOptions", "Hide options") : indT("Dropdown_ShowOptions", "Show options")}
              disabled={readOnlyMode}
            >
              {open ? <ChevronUpSvg className="h-5 w-5" /> : <ChevronDownSvg className="h-5 w-5" />}
            </button>
          </div>
        </div>
        {usePortal ? (
          <FloatingList
            anchorRef={boxRef}
            open={listOpen}
            zIndex={360000}
            fixedWidthPx={resolvedDropdownWidthPx ?? undefined}
            minWidthPx={normalizedDropdownMinWidthPx}
            panelStyle={panelStyle}
            maxHeightClass={dropdownMaxHeightClass}
            role="listbox"
            roundedClass="rounded-[var(--radius-xl)]"
            portalClassName={portalClassName}
            panelClassName={panelClassName}
            widthStrategy={resolvedDropdownWidthStrategy}
            desktopMaxWidthPx={
              resolvedDropdownWidthStrategy === "viewport" ? undefined : DESKTOP_DROPDOWN_MAX_WIDTH_PX
            }
          >
            {listBody}
          </FloatingList>
        ) : (
          listOpen && (
            <div
              className={classNames(
                "absolute z-360000 w-full rounded-[var(--radius-xl)] bg-white shadow-lg ring-1 ring-black/5 focus:outline-hidden overflow-auto",
                inlineDropdownPlacementClass,
                dropdownMaxHeightClass,
                panelClassName || ""
              )}
              style={{ ...inlineDropdownStyle, ...(panelStyle || {}) }}
            >
              {listBody}
            </div>
          )
        )}
      </div>
    </div>
  );
};

export default SelectCombobox;
